//! `affine` generated by `mlirformat tblgen` (`affine.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "affine.gen.rs"]
mod affine;

#[test]
fn affine_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<affine::Affine>();
    common::Fixtures::check_dialect(&opt, "affine");
}
